113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        if (owner.getRegistrationDate() == null) {
119	            owner.setRegistrationDate(LocalDate.now());
120	        }
121	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
122	        if (telephone == null) {
123	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	        }
125	        owner.setTelephone(telephone);
126	        String email = owner.getEmail();
127	        if (email != null) {
128	            email = email.trim();
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email.toLowerCase(Locale.ROOT));
133	        }
134	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
135	            .map(Owner::getTelephone)
136	            .filter(Objects::nonNull)
137	            .map(telephoneNormalizer::normalize)
138	            .anyMatch(telephone::equals);
139	        if (telephoneInUse) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
143	            String lastNameKey = normalizeIdentity(owner.getLastName());
144	            String addressKey = normalizeIdentity(owner.getAddress());
145	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
146	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
147	                    && normalizeIdentity(existing.getAddress()).equals(addressKey));
148	            if (householdDuplicate) {
149	                return new ResponseEntity<>(HttpStatus.CONFLICT);
150	            }
151	        }
152	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
153	        this.clinicService.saveOwner(owner);
154	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
155	        headers.setLocation(UriComponentsBuilder.newInstance()
156	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
157	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
