160	    /**
161	     * Normalize a value for household-identity comparison: null becomes an empty
162	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
163	     * to a single space, and the result is lower-cased.
164	     */
165	    private static String normalizeIdentity(String value) {
166	        if (value == null) {
167	            return "";
168	        }
169	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
170	    }
